import sys

# Increase recursion depth to handle deep nesting (up to 50,000 as specified)
sys.setrecursionlimit(100000)

class JSONParser:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.length = len(text)

    def skip_whitespace(self):
        while self.pos < self.length and self.text[self.pos] in ' \t\n\r':
            self.pos += 1

    def parse_value(self):
        self.skip_whitespace()
        if self.pos >= self.length:
            raise ValueError("Unexpected end of input")

        char = self.text[self.pos]
        if char == '{':
            return self.parse_object()
        elif char == '[':
            return self.parse_array()
        elif char == '"':
            return self.parse_string()
        elif char == '-' or ('0' <= char <= '9'):
            return self.parse_number()
        elif self.text.startswith('true', self.pos):
            self.pos += 4
            return True
        elif self.text.startswith('false', self.pos):
            self.pos += 5
            return False
        elif self.text.startswith('null', self.pos):
            self.pos += 4
            return None
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_object(self):
        self.pos += 1  # skip {
        self.skip_whitespace()
        obj = {}
        if self.pos < self.length and self.text[self.pos] == '}':
            self.pos += 1
            return obj

        while True:
            self.skip_whitespace()
            if self.pos >= self.length or self.text[self.pos] != '"':
                raise ValueError("Key must be a string")
            key = self.parse_string()
            if key in obj:
                raise ValueError("Duplicate key")

            self.skip_whitespace()
            if self.pos >= self.length or self.text[self.pos] != ':':
                raise ValueError("Expected ':' after key")
            self.pos += 1

            val = self.parse_value()
            self.skip_whitespace()

            if self.pos < self.length and self.text[self.pos] == '}':
                self.pos += 1
                return obj

            if self.pos >= self.length or self.text[self.pos] != ',':
                raise ValueError("Expected ',' or '}' in object")
            self.pos += 1

            self.skip_whitespace()
            if self.pos >= self.length or self.text[self.pos] == '}' or self.text[self.pos] == ',':
                raise ValueError("Trailing comma or empty member in object")

    def parse_array(self):
        self.pos += 1  # skip [
        self.skip_whitespace()
        arr = []
        if self.pos < self.length and self.text[self.pos] == ']':
            self.pos += 1
            return arr

        while True:
            val = self.parse_value()
            arr.append(val)
            self.skip_whitespace()

            if self.pos < self.length and self.text[self.pos] == ']':
                self.pos += 1
                return arr

            if self.pos >= self.length or self.text[self.pos] != ',':
                raise ValueError("Expected ',' or ']' in array")
            self.pos += 1

            self.skip_whitespace()
            if self.pos >= self.length or self.text[self.pos] == ']' or self.text[self.pos] == ',':
                raise ValueError("Trailing comma or empty element in array")

    def parse_string(self):
        if self.pos >= self.length or self.text[self.pos] != '"':
            raise ValueError("Expected '\"'")
        self.pos += 1
        res = []
        while self.pos < self.length:
            char = self.text[self.pos]
            if char == '"':
                self.pos += 1
                return "".join(res)
            elif char == '\\':
                self.pos += 1
                if self.pos >= self.length:
                    raise ValueError("Unexpected end of string")
                esc = self.text[self.pos]
                if esc == '"': res.append('"')
                elif esc == '\\': res.append('\\')
                elif esc == '/': res.append('/')
                elif esc == 'b': res.append('\b')
                elif esc == 'f': res.append('\f')
                elif esc == 'n': res.append('\n')
                elif esc == 'r': res.append('\r')
                elif esc == 't': res.append('\t')
                elif esc == 'u':
                    self.pos += 1
                    hex_digits = []
                    for _ in range(4):
                        if self.pos >= self.length:
                            raise ValueError("Incomplete unicode escape")
                        d = self.text[self.pos]
                        if not (('0' <= d <= '9') or ('a' <= d <= 'f') or ('A' <= d <= 'F')):
                            raise ValueError("Invalid hex digit in unicode escape")
                        hex_digits.append(d)
                        self.pos += 1

                    code = int("".join(hex_digits), 16)
                    if 0xD800 <= code <= 0xDBFF:  # High surrogate
                        if self.text.startswith('\\u', self.pos):
                            self.pos += 2
                            low_hex = []
                            for _ in range(4):
                                if self.pos >= self.length:
                                    raise ValueError("Incomplete unicode escape")
                                d = self.text[self.pos]
                                if not (('0' <= d <= '9') or ('a' <= d <= 'f') or ('A' <= d <= 'F')):
                                    raise ValueError("Invalid hex digit in unicode escape")
                                low_hex.append(d)
                                self.pos += 1
                            low_code = int("".join(low_hex), 16)
                            if not (0xDC00 <= low_code <= 0xDFFF):
                                raise ValueError("Invalid surrogate pair")
                            code = 0x10000 + (code - 0xD800) * 0x400 + (low_code - 0xDC00)
                        else:
                            raise ValueError("High surrogate without following low surrogate")
                    elif 0xDC00 <= code <= 0xDFFF:
                        raise ValueError("Low surrogate without preceding high surrogate")
                    res.append(chr(code))
                else:
                    raise ValueError(f"Invalid escape character: \\{esc}")
                self.pos += 1
            elif ord(char) < 0x20:
                raise ValueError("Unescaped control character in string")
            else:
                res.append(char)
                self.pos += 1
        raise ValueError("Unclosed string")

    def parse_number(self):
        start = self.pos
        if self.text[self.pos] == '-':
            self.pos += 1

        if self.pos >= self.length:
            raise ValueError("Number ended prematurely")

        if self.text[self.pos] == '0':
            self.pos += 1
            if self.pos < self.length and '0' <= self.text[self.pos] <= '9':
                raise ValueError("Leading zeros not allowed")
        elif '1' <= self.text[self.pos] <= '9':
            while self.pos < self.length and '0' <= self.text[self.pos] <= '9':
                self.pos += 1
        else:
            raise ValueError("Invalid number start")

        has_float = False
        if self.pos < self.length and self.text[self.pos] == '.':
            has_float = True
            self.pos += 1
            if self.pos >= self.length or not ('0' <= self.text[self.pos] <= '9'):
                raise ValueError("Missing digits after decimal point")
            while self.pos < self.length and '0' <= self.text[self.pos] <= '9':
                self.pos += 1

        has_exp = False
        if self.pos < self.length and self.text[self.pos] in 'eE':
            has_exp = True
            self.pos += 1
            if self.pos < self.length and self.text[self.pos] in '+-':
                self.pos += 1
            if self.pos >= self.length or not ('0' <= self.text[self.pos] <= '9'):
                raise ValueError("Missing digits in exponent")
            while self.pos < self.length and '0' <= self.text[self.pos] <= '9':
                self.pos += 1

        num_str = self.text[start:self.pos]
        if has_float or has_exp:
            return float(num_str)
        else:
            return int(num_str)

def parse_json(text: str) -> object:
    parser = JSONParser(text)
    parser.skip_whitespace()
    if parser.pos >= parser.length:
        raise ValueError("Empty input")
    result = parser.parse_value()
    parser.skip_whitespace()
    if parser.pos != parser.length:
        raise ValueError("Extra data after JSON value")
    return result
